}

function readFile(path) {
  try {
    return fs.readFileSync(path);
  } catch (err) {
    throw err;
  }
}

function readFileWrapped(path) {
  try {
    return fs.readFileSync(path);
  } catch (err) {
    throw new Error("read failed");
  }
}

